target_files.relevant_definitions:
type Event struct { ID, Type(EventType/string), Source, TaskID, FromStatus, ToStatus, Details, CreatedAt }
type EventDelivery struct { EventID, Agent, DeliveredAt, AckedAt(*time.Time) }
type Bus struct { db *gorm.DB }

patterns_to_follow.example:
bus, err := eventbus.New(filepath.Join(t.TempDir(), "test.db"))
if err != nil {
    t.Fatalf("New: %v", err)
}

e := &eventbus.Event{Type: "task.status_changed", Source: "orchestrator", Details: "{}"}
if err := bus.Publish(e); err != nil {
    t.Fatalf("Publish: %v", err)
}
if err := bus.Deliver(e.ID, "watcher-agent"); err != nil {
    t.Fatalf("Deliver: %v", err)
}

base := t.TempDir()
inbox := filepath.Join(base, "mike", "inbox")
if err := os.MkdirAll(inbox, 0o755); err != nil {
    t.Fatal(err)
}
if err := os.WriteFile(filepath.Join(inbox, "20260329-011834-kyle.md"), []byte("hello"), 0o644); err != nil {
    t.Fatal(err)
}

remaining, err := bus.UnackedDeliveries("watcher-agent")
if err != nil {
    t.Fatalf("UnackedDeliveries: %v", err)
}
if len(remaining) != 0 {
    t.Errorf("got %d unacked events, want 0", len(remaining))
}
